using UnityEngine;
using UnityEngine.UI;

public class GameFlowManagerMain : MonoBehaviour {
    GameObject mainCam;
    GameObject uiCanvas;
    GameObject btnStart;
    GameObject hand;
    GameObject endCard;
    int currentPhase = 0;
    float timer = 0f;
    bool isPlaying = false;
    float phaseTimer = 0f;

    void Start() {
        mainCam = GameObject.Find("__Camera");
        uiCanvas = GameObject.Find("__UICanvas");
        btnStart = GameObject.Find("__UI_Btn_Start");
        hand = GameObject.Find("__UI_Hand");
        endCard = GameObject.Find("__UI_EndCard");
        var ground = GameObject.Find("__Ground");
        var pool1 = GameObject.Find("__Pool_Cube_Red_01");
        var pool2 = GameObject.Find("__Pool_Cube_Blue_01");
        var pool3 = GameObject.Find("__Pool_Sphere_Green_01");
        var pool4 = GameObject.Find("__Pool_Cylinder_Yellow_01");
        var pool5 = GameObject.Find("__Pool_Cube_Red_02");
        var pool6 = GameObject.Find("__Pool_Cube_Blue_02");
        pool1.transform.position = new Vector3(0, 0, 0);
        pool2.transform.position = new Vector3(2, 0, 0);
        pool3.transform.position = new Vector3(4, 0, 0);
        pool4.transform.position = new Vector3(6, 0, 0);
        pool5.transform.position = new Vector3(0, 0, 2);
        pool6.transform.position = new Vector3(2, 0, 2);
        SetupUI();
        StartPhase(0);
    }

    void SetupUI() {
        if (btnStart != null) {
            var btn = (Button)btnStart.GetComponent(typeof(Button));
            if (btn != null) {
                btn.onClick.AddListener(OnStartClick);
            }
        }
        if (hand != null) {
            hand.transform.position = new Vector3(0, -999, 0);
        }
        if (endCard != null) {
            endCard.transform.position = new Vector3(0, -999, 0);
        }
    }

    void OnStartClick() {
        isPlaying = true;
        currentPhase = 1;
        phaseTimer = 0f;
        if (btnStart != null) {
            btnStart.transform.position = new Vector3(0, -999, 0);
        }
    }

    void StartPhase(int phase) {
        currentPhase = phase;
        phaseTimer = 0f;
        if (phase == 0) {
            ShowHand(true);
        } else if (phase == 1) {
            ShowHand(false);
        } else if (phase == 2) {
            ShowEndCard();
        }
    }

    void ShowHand(bool show) {
        if (hand == null) return;
        if (show) {
            hand.transform.position = new Vector3(1, 1, 0);
        } else {
            hand.transform.position = new Vector3(0, -999, 0);
        }
    }

    void ShowEndCard() {
        if (endCard == null) return;
        endCard.transform.position = new Vector3(0, 0, 0);
        Luna.Unity.Playable.InstallFullGame();
    }

    void Update() {
        if (!isPlaying) return;
        timer += Time.deltaTime;
        phaseTimer += Time.deltaTime;

        if (currentPhase == 0) {
            UpdatePhase0();
        } else if (currentPhase == 1) {
            UpdatePhase1();
        }
    }

    void UpdatePhase0() {
        if (phaseTimer > 3f) {
            StartPhase(1);
        }
    }

    void UpdatePhase1() {
        var obj = GameObject.Find("__Pool_Cube_Red_01");
        if (obj != null) {
            obj.transform.position = new Vector3(
                Mathf.Sin(timer) * 2f,
                0,
                Mathf.Cos(timer) * 2f
            );
        }
        if (phaseTimer > 5f) {
            StartPhase(2);
        }
    }

    void OnDestroy() {
        isPlaying = false;
    }
}
